return function(Plasma)
	local create = Plasma.create

	local Item = Plasma.widget(function(text, paraType)
		local clicked, setClicked = Plasma.useState(false)
		local style = Plasma.useStyle()

		local refs = Plasma.useInstance(function(ref)
			local button = create("Frame", {
				[ref] = "frame",
				Size = UDim2.new(1, 0, 0, 40),
				BackgroundTransparency = 1,
				
				create("UIListLayout", {
					SortOrder = Enum.SortOrder.LayoutOrder,
					FillDirection = Enum.FillDirection.Horizontal,
					Padding = UDim.new(0, 10),
				}),
				create("Frame", {
					BackgroundTransparency = .5,
					BackgroundColor3 = style.bg3,
					Size = UDim2.new(.5, -5, 1, 0),
					create("UIPadding", {
						PaddingBottom = UDim.new(0, 0),
						PaddingLeft = UDim.new(0, 8),
						PaddingRight = UDim.new(0, 8),
						PaddingTop = UDim.new(0, 0),
					}),
					
					create("UICorner", {
						CornerRadius = UDim.new(0, 8),
					}),

					create("TextLabel", {
						BackgroundTransparency = 1,
						Size = UDim2.new(1, 0, 1, 0),
						Text = text,
						TextXAlignment = Enum.TextXAlignment.Left,
						TextSize = 22,
						TextColor3 = style.textColor,
						Font = Enum.Font.Gotham,
						TextTruncate = Enum.TextTruncate.AtEnd,
					}),
				}),
				
				create("TextBox", {
					[ref] = "input",
					PlaceholderText = string.gsub(paraType, "System.", ''),
					BackgroundTransparency = .9,
					BackgroundColor3 = style.bg4,
					Size = UDim2.new(.5, -5, 1, 0),
					Text = "",
					TextXAlignment = Enum.TextXAlignment.Left,
					TextSize = 22,
					TextColor3 = style.textColor,
					Font = Enum.Font.Gotham,
					TextTruncate = Enum.TextTruncate.AtEnd,
					ClearTextOnFocus = false,
					create("UICorner", {
						CornerRadius = UDim.new(0, 8),
					}),
					create("UIPadding", {
						PaddingBottom = UDim.new(0, 0),
						PaddingLeft = UDim.new(0, 8),
						PaddingRight = UDim.new(0, 8),
						PaddingTop = UDim.new(0, 0),
					}),
				}),
			})
			return button
		end)

		Plasma.useEffect(function()
			refs.frame.Frame.TextLabel.Text = text .. ": "
			refs.input.PlaceholderText = string.gsub(paraType, "System.", '')
			refs.input.Text = ""
		end, text)


		return refs.input.Text
	end)

	return Plasma.widget(function(items, paraTypes, options)
		options = options or {}

		Plasma.useInstance(function()
			local frame = create("Frame", {
				BackgroundTransparency = 1,
				Size = options.width and UDim2.new(0, options.width, 0, 0) or UDim2.new(1, 0, 0, 0),

				create("UIListLayout", {
					SortOrder = Enum.SortOrder.LayoutOrder,
					FillDirection = Enum.FillDirection.Vertical,
					Padding = UDim.new(0, 10),
				}),
			})

			Plasma.automaticSize(frame, {
				axis = Enum.AutomaticSize.Y,
			})

			return frame
		end)

		local inputs = {}
		for i, v in pairs(items) do
			local text = Item(v.text, paraTypes[i])
			table.insert(inputs, text)
		end

		return inputs
	end)
end
